insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level, question, options, correct_index, explanation, topic, is_general, semester, units)
values
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{1}{(x-1)(x-3)}$?', '["$(-\\infty,1)\\cup(1,3)\\cup(3,\\infty)$", "$(-\\infty,1)\\cup(3,\\infty)$", "$(1,3)$", "$\\mathbb{R}$"]'::jsonb, 0, 'Division by zero is not allowed, so $x \neq 1$ and $x \neq 3$. The domain is all reals except these two points, i.e. $(-\infty,1)\cup(1,3)\cup(3,\infty)$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the natural domain of $f(x) = \dfrac{1}{\sqrt{x^2-5x+6}}$.', '["$(-\\infty,2)\\cup(3,\\infty)$", "$(2,3)$", "$[2,3]$", "$(-\\infty,2]\\cup[3,\\infty)$"]'::jsonb, 0, 'We need $x^2-5x+6 > 0$ (strict, since it sits under a square root in a denominator). Since $x^2-5x+6=(x-2)(x-3)$, this product is positive when $x<2$ or $x>3$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Determine the domain and range of $f(x) = 3+\sqrt{x-1}$.', '["Domain $[1,\\infty)$, range $[3,\\infty)$", "Domain $[1,\\infty)$, range $[0,\\infty)$", "Domain $[3,\\infty)$, range $[1,\\infty)$", "Domain $\\mathbb{R}$, range $[3,\\infty)$"]'::jsonb, 0, 'We need $x-1\geq 0$, so the domain is $[1,\infty)$. As $x$ ranges over $[1,\infty)$, $\sqrt{x-1}$ ranges over $[0,\infty)$, so $f(x)=3+\sqrt{x-1}$ ranges over $[3,\infty)$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Determine the domain and range of $f(x) = \dfrac{x+1}{x-1}$.', '["Domain $x\\neq 1$, range $y\\neq 1$", "Domain $x\\neq -1$, range $y\\neq -1$", "Domain $x\\neq 1$, range $y\\neq -1$", "Domain $\\mathbb{R}$, range $\\mathbb{R}$"]'::jsonb, 0, 'The function is undefined at $x=1$. Writing $x=\frac{y+1}{y-1}$ after solving for $x$ in terms of $y$ shows $y=1$ can never be attained, so the range excludes $1$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the natural domain of $f(x) = \sqrt{\dfrac{1}{x+2}}$.', '["$(-2,\\infty)$", "$[-2,\\infty)$", "$(-\\infty,-2)$", "$\\mathbb{R}\\setminus\\{-2\\}$"]'::jsonb, 0, 'We need $\frac{1}{x+2} \geq 0$, and since it is a denominator we also need $x \neq -2$. Combining, $x+2>0$, i.e. $x>-2$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the range of $y = 1+\dfrac{1}{x}$.', '["$(-\\infty,1)\\cup(1,\\infty)$", "$(-\\infty,0)\\cup(0,\\infty)$", "$[1,\\infty)$", "$(-\\infty,1]$"]'::jsonb, 0, 'Since $\frac{1}{x}$ can be any real number except $0$, $y=1+\frac1x$ can be any real number except $1$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{1}{x^2-4}$?', '["$(-\\infty,-2)\\cup(-2,2)\\cup(2,\\infty)$", "$(-2,2)$", "$(-\\infty,-2)\\cup(2,\\infty)$", "$\\mathbb{R}$"]'::jsonb, 0, 'The denominator $x^2-4=(x-2)(x+2)$ vanishes at $x=\pm 2$, so these two values must be excluded from the domain.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the domain and range of $y=\sqrt{x+4}$.', '["Domain $x\\geq -4$, range $y\\geq 0$", "Domain $x\\geq -4$, range $y>0$", "Domain $x\\geq 4$, range $y\\geq 0$", "Domain $\\mathbb{R}$, range $y\\geq 0$"]'::jsonb, 0, 'The expression under the square root must be non-negative: $x+4\geq 0 \Rightarrow x\geq -4$. Since a square root is never negative, the range is $y\geq 0$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the domain and range of $y=\sqrt{3-x}$.', '["Domain $x\\leq 3$, range $y\\geq 0$", "Domain $x\\geq 3$, range $y\\geq 0$", "Domain $x\\leq 3$, range $y>0$", "Domain $x < 3$, range $y > 0$"]'::jsonb, 0, 'We require $3-x\geq 0$, i.e. $x\leq 3$. The square root always returns a value $\geq 0$, so the range is $y \geq 0$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{1}{x^2-x-2}$?', '["$\\mathbb{R}\\setminus\\{-1,2\\}$", "$\\mathbb{R}\\setminus\\{1,-2\\}$", "$(-1,2)$", "$\\mathbb{R}$"]'::jsonb, 0, 'Factoring, $x^2-x-2=(x-2)(x+1)$, which is zero when $x=2$ or $x=-1$. These values must be excluded.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the natural domain of $f(x) = \sqrt{1-x^2}$.', '["$[-1,1]$", "$(-1,1)$", "$(-\\infty,-1]\\cup[1,\\infty)$", "$\\mathbb{R}$"]'::jsonb, 0, 'We need $1-x^2 \geq 0$, i.e. $x^2 \leq 1$, which holds precisely for $-1 \leq x \leq 1$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{1}{\sqrt{x^2-5}}$?', '["$(-\\infty,-\\sqrt5)\\cup(\\sqrt5,\\infty)$", "$(-\\sqrt5,\\sqrt5)$", "$[\\sqrt5,\\infty)$", "$\\mathbb{R}\\setminus\\{\\pm\\sqrt5\\}$"]'::jsonb, 0, 'We need $x^2-5>0$ (strict inequality, since it is under a square root that sits in a denominator), which holds when $x<-\sqrt5$ or $x>\sqrt5$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{x+2}{x^2-9}$?', '["$\\mathbb{R}\\setminus\\{-3,3\\}$", "$(-3,3)$", "$\\mathbb{R}\\setminus\\{-2\\}$", "$\\mathbb{R}$"]'::jsonb, 0, 'The denominator $x^2-9=(x-3)(x+3)$ is zero at $x=\pm3$, so these values are excluded from the domain.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the natural domain of $f(x) = \dfrac{x}{x^2-x-6}$?', '["$\\mathbb{R}\\setminus\\{-2,3\\}$", "$\\mathbb{R}\\setminus\\{2,-3\\}$", "$(-2,3)$", "$\\mathbb{R}\\setminus\\{0\\}$"]'::jsonb, 0, 'Factoring the denominator, $x^2-x-6=(x-3)(x+2)$, which vanishes at $x=3$ and $x=-2$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = x^2 + \dfrac{1}{x}$, what is $f(-2)$?', '["$\\dfrac{7}{2}$", "$\\dfrac{9}{2}$", "$-\\dfrac{7}{2}$", "$\\dfrac{7}{4}$"]'::jsonb, 0, '$f(-2) = (-2)^2 + \frac{1}{-2} = 4 - \frac12 = \frac72$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Let $\lfloor x \rfloor$ denote the greatest integer less than or equal to $x$. If $f(x) = \lfloor x \rfloor - x$, what is $f(-1.9)$?', '["$-0.1$", "$0.1$", "$-1.9$", "$1.9$"]'::jsonb, 0, '$\lfloor -1.9 \rfloor = -2$ (the greatest integer not exceeding $-1.9$), so $f(-1.9) = -2-(-1.9) = -0.1$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = |x| - x^2$, what is $f(-2)$?', '["$-2$", "$2$", "$6$", "$-6$"]'::jsonb, 0, '$f(-2) = |-2| - (-2)^2 = 2 - 4 = -2$.', 'Real-valued Functions of a Real Variable', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = 2x+1$ and $g(x) = x^2-5$, find $(f\circ g)(x)$.', '["$2x^2-9$", "$2x^2-5$", "$2x^2+1$", "$4x^2-9$"]'::jsonb, 0, '$(f\circ g)(x) = f(g(x)) = 2(x^2-5)+1 = 2x^2-10+1 = 2x^2-9$.', 'Composition of Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = 3x-2$ and $g(x) = |3x+2|$, find $(g\circ f)(-3)$.', '["$31$", "$-31$", "$29$", "$-29$"]'::jsonb, 0, 'First $f(-3) = 3(-3)-2 = -11$. Then $g(-11) = |3(-11)+2| = |-33+2| = |-31| = 31$.', 'Composition of Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = x+3$ and $g(x) = x-2$, find $(f\circ g)(x)$.', '["$x+1$", "$x-1$", "$x+5$", "$x-5$"]'::jsonb, 0, '$(f\circ g)(x) = f(g(x)) = (x-2)+3 = x+1$.', 'Composition of Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the inverse of $f(x) = 2x-3$.', '["$f^{-1}(x) = \\dfrac{x+3}{2}$", "$f^{-1}(x) = \\dfrac{x-3}{2}$", "$f^{-1}(x) = 2x+3$", "$f^{-1}(x) = \\dfrac{x}{2}-3$"]'::jsonb, 0, 'Write $y=2x-3$, solve for $x$: $x=\frac{y+3}{2}$. Swapping $x$ and $y$ gives $f^{-1}(x)=\frac{x+3}{2}$.', 'The Inverse of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the inverse of $f(x) = 4x+5$.', '["$f^{-1}(x) = \\dfrac{x-5}{4}$", "$f^{-1}(x) = \\dfrac{x+5}{4}$", "$f^{-1}(x) = 4x-5$", "$f^{-1}(x) = \\dfrac{x-4}{5}$"]'::jsonb, 0, 'Write $y=4x+5$, solve for $x$: $x=\frac{y-5}{4}$. Swapping $x$ and $y$ gives $f^{-1}(x)=\frac{x-5}{4}$.', 'The Inverse of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the inverse of $f(x) = \dfrac{x}{2}+3$.', '["$f^{-1}(x) = 2x-6$", "$f^{-1}(x) = 2x+6$", "$f^{-1}(x) = \\dfrac{x-3}{2}$", "$f^{-1}(x) = 2(x+3)$"]'::jsonb, 0, 'Write $y=\frac{x}{2}+3$, solve for $x$: $x = 2(y-3)=2y-6$. Swapping $x$ and $y$ gives $f^{-1}(x)=2x-6$.', 'The Inverse of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $f(x) = \ln(3x+4)$, what value of $x$ satisfies $f(x)=0$?', '["$-1$", "$1$", "$0$", "$-\\dfrac43$"]'::jsonb, 0, '$\ln(3x+4)=0 \Rightarrow 3x+4 = e^0 = 1 \Rightarrow 3x=-3 \Rightarrow x=-1$.', 'The Inverse of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the inverse of $f(x) = 4x-7$.', '["$f^{-1}(x) = \\dfrac{x+7}{4}$", "$f^{-1}(x) = \\dfrac{x-7}{4}$", "$f^{-1}(x) = 4x+7$", "$f^{-1}(x) = \\dfrac{x}{4}+7$"]'::jsonb, 0, 'Write $y=4x-7$, solve for $x$: $x=\frac{y+7}{4}$. Swapping $x$ and $y$ gives $f^{-1}(x)=\frac{x+7}{4}$.', 'The Inverse of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 1}\dfrac{x^2+x-2}{x-1}$.', '["$3$", "$1$", "$-1$", "$0$"]'::jsonb, 0, 'Factor the numerator: $x^2+x-2=(x+2)(x-1)$, so the expression equals $x+2$ for $x\neq1$. Then the limit is $1+2=3$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 2}\dfrac{x^2-4}{x^2-x-2}$.', '["$\\dfrac43$", "$\\dfrac34$", "$2$", "$0$"]'::jsonb, 0, 'Factor both parts: $\frac{(x-2)(x+2)}{(x-2)(x+1)} = \frac{x+2}{x+1}$ for $x\neq 2$. At $x=2$, this is $\frac{4}{3}$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 3}\dfrac{x^2-x-6}{x^2-9}$.', '["$\\dfrac56$", "$\\dfrac65$", "$1$", "$0$"]'::jsonb, 0, 'Factor: $\frac{(x-3)(x+2)}{(x-3)(x+3)} = \frac{x+2}{x+3}$ for $x\neq3$. At $x=3$, this is $\frac{5}{6}$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 2}\dfrac{x^2-4}{x^2+4}$.', '["$0$", "$1$", "$\\dfrac12$", "$\\infty$"]'::jsonb, 0, 'Direct substitution is valid since the denominator is nonzero at $x=2$: $\frac{4-4}{4+4}=\frac{0}{8}=0$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to -1}\dfrac{x^2+2}{x^2+1}$.', '["$\\dfrac32$", "$1$", "$3$", "$\\dfrac23$"]'::jsonb, 0, 'Direct substitution is valid: $\frac{(-1)^2+2}{(-1)^2+1} = \frac{3}{2}$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 9}\dfrac{x-9}{\sqrt{x}-3}$.', '["$6$", "$3$", "$9$", "$\\dfrac16$"]'::jsonb, 0, 'Multiply numerator and denominator by $\sqrt{x}+3$: $\frac{(x-9)(\sqrt x+3)}{x-9} = \sqrt x + 3$, which tends to $3+3=6$ as $x\to 9$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 4}\dfrac{\sqrt{x}-2}{x-4}$.', '["$\\dfrac14$", "$\\dfrac12$", "$4$", "$0$"]'::jsonb, 0, 'Multiply by the conjugate: $\frac{\sqrt x-2}{x-4}=\frac{1}{\sqrt x+2}$ for $x\neq4$, which tends to $\frac{1}{2+2}=\frac14$.', 'Limits of Polynomial and Rational Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{x^3}{5x^4+2}$.', '["$0$", "$\\dfrac15$", "$\\infty$", "$1$"]'::jsonb, 0, 'The denominator has a higher degree than the numerator, so dividing every term by $x^4$ shows the limit is $0$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{3x^2-5x-1}{2x-5x^2}$.', '["$-\\dfrac35$", "$\\dfrac35$", "$-\\dfrac25$", "$\\infty$"]'::jsonb, 0, 'Both numerator and denominator have degree 2. Dividing by $x^2$, the limit is the ratio of leading coefficients: $\frac{3}{-5}=-\frac35$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{2x^3+x^2+5}{3x^3-x^2-6}$.', '["$\\dfrac23$", "$\\dfrac32$", "$1$", "$0$"]'::jsonb, 0, 'Both numerator and denominator have degree 3. Dividing by $x^3$, the limit is the ratio of leading coefficients: $\frac23$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{4x^2+10x-5}{x^2+4x+10}$.', '["$4$", "$1$", "$10$", "$\\infty$"]'::jsonb, 0, 'Both numerator and denominator have degree 2. Dividing by $x^2$, the limit is the ratio of leading coefficients: $\frac41=4$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{3+x+3x^2}{3x^2-3}$.', '["$1$", "$3$", "$\\dfrac13$", "$0$"]'::jsonb, 0, 'Both are degree-2 polynomials in $x$. Dividing every term by $x^2$, the limit is the ratio of leading coefficients: $\frac33=1$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{2x^2-3x+1}{3x^2-5x-1}$.', '["$\\dfrac23$", "$-\\dfrac23$", "$1$", "$0$"]'::jsonb, 0, 'Dividing by $x^2$, the limit is the ratio of leading coefficients: $\frac23$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to\infty}\dfrac{3x^3+x^2-1}{2x^3+1}$.', '["$\\dfrac32$", "$\\dfrac23$", "$1$", "$\\infty$"]'::jsonb, 0, 'Both numerator and denominator have degree 3. Dividing by $x^3$, the limit is the ratio of leading coefficients: $\frac32$.', 'Limit at Infinity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{\sin 2x}{x}$.', '["$2$", "$1$", "$0$", "$\\dfrac12$"]'::jsonb, 0, 'Write $\frac{\sin2x}{x} = 2\cdot\frac{\sin2x}{2x}$. Since $\frac{\sin u}{u}\to1$ as $u\to0$, the limit is $2\cdot1=2$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{\sin 2x}{3x}$.', '["$\\dfrac23$", "$\\dfrac32$", "$2$", "$0$"]'::jsonb, 0, 'Write $\frac{\sin2x}{3x} = \frac23\cdot\frac{\sin2x}{2x}\to \frac23\cdot1=\frac23$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{\sin 3x}{2x}$.', '["$\\dfrac32$", "$\\dfrac23$", "$3$", "$0$"]'::jsonb, 0, 'Write $\frac{\sin3x}{2x} = \frac32\cdot\frac{\sin3x}{3x}\to \frac32\cdot1=\frac32$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{1-\cos x}{\sin^2 x}$.', '["$\\dfrac12$", "$1$", "$0$", "$2$"]'::jsonb, 0, 'Multiply numerator and denominator by $1+\cos x$: $\frac{(1-\cos x)(1+\cos x)}{\sin^2x(1+\cos x)} = \frac{\sin^2x}{\sin^2x(1+\cos x)} = \frac{1}{1+\cos x} \to \frac{1}{2}$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{x^2}{1-\cos x}$.', '["$2$", "$\\dfrac12$", "$1$", "$0$"]'::jsonb, 0, 'By L''Hopital''s rule applied twice: $\lim\frac{2x}{\sin x} = \lim\frac{2}{\cos x} = 2$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{\tan 3x}{2x}$.', '["$\\dfrac32$", "$\\dfrac23$", "$3$", "$0$"]'::jsonb, 0, 'Write $\tan3x = \frac{\sin3x}{\cos3x}$, so $\frac{\tan3x}{2x} = \frac{3}{2}\cdot\frac{\sin3x}{3x}\cdot\frac{1}{\cos3x} \to \frac32\cdot1\cdot1=\frac32$.', 'Limits of Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{5x-\sin x}{x}$.', '["$4$", "$5$", "$6$", "$0$"]'::jsonb, 0, 'This is a $\frac00$ form. By L''Hopital''s rule, $\lim_{x\to0}\frac{5-\cos x}{1} = 5-1=4$.', 'Indeterminate Forms and L''Hopital''s Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{\sqrt{1-x}-1+\frac{x}{2}}{x^2}$.', '["$-\\dfrac18$", "$\\dfrac18$", "$-\\dfrac14$", "$0$"]'::jsonb, 0, 'This is a $\frac00$ form. Applying L''Hopital''s rule twice: first derivative gives $\frac{-\frac{1}{2\sqrt{1-x}}+\frac12}{2x}$, still $\frac00$; differentiating again and letting $x\to0$ yields $-\frac18$.', 'Indeterminate Forms and L''Hopital''s Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{x\cos x-\sin x}{x^3}$.', '["$-\\dfrac13$", "$\\dfrac13$", "$0$", "$-1$"]'::jsonb, 0, 'This is a $\frac00$ form. Differentiating top and bottom repeatedly (L''Hopital''s rule, applied twice) and simplifying gives the limit $-\frac13$.', 'Indeterminate Forms and L''Hopital''s Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\lim_{x\to 0}\dfrac{x-\sin x\cos x}{x^3}$.', '["$\\dfrac23$", "$\\dfrac13$", "$1$", "$0$"]'::jsonb, 0, 'Using $\sin x\cos x=\frac12\sin2x$, this is a $\frac00$ form. Applying L''Hopital''s rule three times gives the limit $\frac23$.', 'Indeterminate Forms and L''Hopital''s Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $c$ is $f(x)=\begin{cases}\dfrac{x^2-1}{x+1}, & x\neq -1\\ c, & x=-1\end{cases}$ continuous at $x=-1$?', '["$-2$", "$2$", "$0$", "$-1$"]'::jsonb, 0, 'For continuity, $c$ must equal $\lim_{x\to-1}\frac{x^2-1}{x+1} = \lim_{x\to-1}(x-1) = -2$.', 'Continuous Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $k$ is $f(x)=\begin{cases}\dfrac{\sqrt{x}-1}{x-1}, & x\neq 1\\ k, & x=1\end{cases}$ continuous at $x=1$?', '["$\\dfrac12$", "$1$", "$2$", "$0$"]'::jsonb, 0, 'For continuity, $k$ must equal $\lim_{x\to1}\frac{\sqrt x-1}{x-1} = \lim_{x\to1}\frac{1}{\sqrt x+1} = \frac12$.', 'Continuous Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $c$ is $f(x)=\begin{cases}x^2-x, & x\leq 1\\ c-x, & x>1\end{cases}$ continuous at $x=1$?', '["$1$", "$0$", "$2$", "$-1$"]'::jsonb, 0, 'The left-hand limit at $x=1$ is $1^2-1=0$. For continuity, the right piece must also give $0$ there: $c-1=0 \Rightarrow c=1$.', 'Continuous Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'At which value(s) of $x$ is $f(x)=\dfrac{5+x}{2x-x^2}$ discontinuous?', '["$x=0$ and $x=2$", "$x=-5$ only", "$x=0$ only", "$x=2$ only"]'::jsonb, 0, 'The denominator $2x-x^2=x(2-x)$ vanishes at $x=0$ and $x=2$, and the numerator does not vanish there, so both are points of discontinuity.', 'Types of Discontinuity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Consider $f(x)=\dfrac{x^2-5x+6}{x^2+2x-8}$. What type of discontinuity occurs at $x=2$?', '["Removable", "Non-removable (infinite)", "Jump", "There is no discontinuity at $x=2$"]'::jsonb, 0, 'Factoring, $f(x)=\frac{(x-2)(x-3)}{(x+4)(x-2)}=\frac{x-3}{x+4}$ for $x\neq2$. The limit as $x\to2$ exists and equals $-\frac16$, but $f(2)$ is undefined, so the discontinuity at $x=2$ is removable.', 'Types of Discontinuity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What type of discontinuity does $f(x)=\dfrac{x^2-6x+9}{x^2-4x+3}$ have at $x=3$?', '["Removable", "Non-removable (infinite)", "Jump", "There is no discontinuity at $x=3$"]'::jsonb, 0, 'Factoring, $f(x)=\frac{(x-3)^2}{(x-1)(x-3)}=\frac{x-3}{x-1}$ for $x\neq3$. The limit as $x\to3$ is $0$ (finite), but $f(3)$ is undefined, so the discontinuity is removable.', 'Types of Discontinuity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'At which value(s) of $x$ is $f(x)=\dfrac{2x^2+5}{x^3+x^2-2x}$ discontinuous?', '["$x=-2,\\ 0,\\ 1$", "$x=-2,\\ 1$ only", "$x=0$ only", "$x=2,\\ 0,\\ -1$"]'::jsonb, 0, 'Factor the denominator: $x^3+x^2-2x = x(x^2+x-2) = x(x+2)(x-1)$, which vanishes at $x=0,-2,1$. The numerator is nonzero at each, so $f$ is discontinuous at all three.', 'Types of Discontinuity', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{2-x}{x^2}$.', '["$\\dfrac{x-4}{x^3}$", "$\\dfrac{x+4}{x^3}$", "$\\dfrac{4-x}{x^3}$", "$\\dfrac{-2}{x^3}$"]'::jsonb, 0, 'Write $y = 2x^{-2}-x^{-1}$, so $y'' = -4x^{-3}+x^{-2} = \frac{x-4}{x^3}$ after combining over a common denominator.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sqrt{x} + \cos x$.', '["$\\dfrac{1}{2\\sqrt{x}} - \\sin x$", "$\\dfrac{1}{2\\sqrt{x}} + \\sin x$", "$\\dfrac{1}{\\sqrt{x}} - \\sin x$", "$2\\sqrt{x} - \\sin x$"]'::jsonb, 0, 'Differentiate term by term: $\frac{d}{dx}\sqrt x = \frac{1}{2\sqrt x}$ and $\frac{d}{dx}\cos x = -\sin x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sqrt{x} - \ln x$.', '["$\\dfrac{1}{2\\sqrt{x}} - \\dfrac{1}{x}$", "$\\dfrac{1}{2\\sqrt{x}} + \\dfrac{1}{x}$", "$\\dfrac{1}{\\sqrt{x}} - \\dfrac{1}{x}$", "$\\dfrac{1}{2\\sqrt{x}} - x$"]'::jsonb, 0, 'Differentiate term by term: $\frac{d}{dx}\sqrt x = \frac{1}{2\sqrt x}$ and $\frac{d}{dx}\ln x = \frac1x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = 25x^3$.', '["$75x^2$", "$25x^2$", "$75x^3$", "$25x^4$"]'::jsonb, 0, 'Using the constant-multiple and power rules, $y'' = 25\cdot3x^2 = 75x^2$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{1}{3}x^9$.', '["$3x^8$", "$9x^8$", "$\\dfrac13 x^8$", "$3x^9$"]'::jsonb, 0, '$y'' = \frac13\cdot9x^8 = 3x^8$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = (3+2x)(x-1)$.', '["$4x+1$", "$4x-1$", "$2x+1$", "$4x+3$"]'::jsonb, 0, 'Expand first: $y = 2x^2+x-3$, so $y'' = 4x+1$. (This also follows directly from the product rule.)', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \left(x^3+3x\right)^{17}$.', '["$51(x^2+1)(x^2+3)^{16}$", "$17(x^3+3x)^{16}$", "$51x^2(x^3+3x)^{16}$", "$17(3x^2+3)^{16}$"]'::jsonb, 0, 'By the chain rule, $y''=17(x^3+3x)^{16}\cdot(3x^2+3) = 51(x^2+1)(x^2+3)^{16}$ after factoring $3x^2+3=3(x^2+1)$ and noting $x^3+3x=x(x^2+3)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sin\left(e^{2x}\right)$.', '["$2e^{2x}\\cos(e^{2x})$", "$e^{2x}\\cos(e^{2x})$", "$2e^{2x}\\sin(e^{2x})$", "$-2e^{2x}\\cos(e^{2x})$"]'::jsonb, 0, 'By the chain rule, $y'' = \cos(e^{2x})\cdot\frac{d}{dx}(e^{2x}) = 2e^{2x}\cos(e^{2x})$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sin(x^2+3)$.', '["$2x\\cos(x^2+3)$", "$\\cos(x^2+3)$", "$2x\\sin(x^2+3)$", "$-2x\\cos(x^2+3)$"]'::jsonb, 0, 'By the chain rule, $y'' = \cos(x^2+3)\cdot 2x = 2x\cos(x^2+3)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \tan(x^2)$.', '["$2x\\sec^2(x^2)$", "$\\sec^2(x^2)$", "$2x\\tan(x^2)$", "$x^2\\sec^2(x^2)$"]'::jsonb, 0, 'By the chain rule, $y'' = \sec^2(x^2)\cdot2x = 2x\sec^2(x^2)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = e^{x^2+2}$.', '["$2xe^{x^2+2}$", "$e^{x^2+2}$", "$x^2 e^{x^2+2}$", "$2e^{x^2+2}$"]'::jsonb, 0, 'By the chain rule, $y'' = e^{x^2+2}\cdot 2x = 2xe^{x^2+2}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = (x^2+x)^9$.', '["$9(2x+1)(x^2+x)^8$", "$9(x^2+x)^8$", "$18x(x^2+x)^8$", "$(2x+1)(x^2+x)^8$"]'::jsonb, 0, 'By the chain rule, $y'' = 9(x^2+x)^8\cdot(2x+1)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \cos(2x^2+1)$.', '["$-4x\\sin(2x^2+1)$", "$4x\\sin(2x^2+1)$", "$-4x\\cos(2x^2+1)$", "$-\\sin(2x^2+1)$"]'::jsonb, 0, 'By the chain rule, $y'' = -\sin(2x^2+1)\cdot 4x = -4x\sin(2x^2+1)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $D_x\left[\tan(\cos x)\right]$.', '["$-\\sin x\\sec^2(\\cos x)$", "$\\sin x\\sec^2(\\cos x)$", "$-\\cos x\\sec^2(\\cos x)$", "$\\sec^2(\\cos x)$"]'::jsonb, 0, 'By the chain rule, $D_x[\tan(\cos x)] = \sec^2(\cos x)\cdot(-\sin x) = -\sin x\sec^2(\cos x)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $D_x\left[\tan(\sin x)\right]$.', '["$\\cos x\\sec^2(\\sin x)$", "$-\\cos x\\sec^2(\\sin x)$", "$\\sin x\\sec^2(\\sin x)$", "$\\sec^2(\\sin x)$"]'::jsonb, 0, 'By the chain rule, $D_x[\tan(\sin x)] = \sec^2(\sin x)\cdot\cos x$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the differential coefficient of $y = (1+x^2)^2$.', '["$4x(x^2+1)$", "$2(x^2+1)$", "$4x(x^2+1)^2$", "$2x(x^2+1)$"]'::jsonb, 0, 'By the chain rule, $y'' = 2(1+x^2)\cdot2x = 4x(x^2+1)$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sin(\ln x^2)$.', '["$\\dfrac{2\\cos(\\ln x^2)}{x}$", "$\\dfrac{\\cos(\\ln x^2)}{x}$", "$\\dfrac{2\\cos(\\ln x^2)}{x^2}$", "$2x\\cos(\\ln x^2)$"]'::jsonb, 0, 'By the chain rule, $y'' = \cos(\ln x^2)\cdot\frac{2x}{x^2} = \frac{2\cos(\ln x^2)}{x}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = e^{x^2+2x}$.', '["$2(x+1)e^{x^2+2x}$", "$(2x+2)$", "$e^{x^2+2x}$", "$(x+1)e^{x^2+2x}$"]'::jsonb, 0, 'By the chain rule, $y'' = e^{x^2+2x}\cdot(2x+2) = 2(x+1)e^{x^2+2x}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = (3x^2-2)^3$.', '["$18x(3x^2-2)^2$", "$3(3x^2-2)^2$", "$6x(3x^2-2)^2$", "$18x(3x^2-2)^3$"]'::jsonb, 0, 'By the chain rule, $y'' = 3(3x^2-2)^2\cdot6x = 18x(3x^2-2)^2$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sqrt{1-2x^3}$.', '["$\\dfrac{-3x^2}{\\sqrt{1-2x^3}}$", "$\\dfrac{-6x^2}{\\sqrt{1-2x^3}}$", "$\\dfrac{3x^2}{\\sqrt{1-2x^3}}$", "$\\dfrac{-3x^2}{2\\sqrt{1-2x^3}}$"]'::jsonb, 0, 'Write $y=(1-2x^3)^{1/2}$. Then $y''=\frac12(1-2x^3)^{-1/2}\cdot(-6x^2) = \frac{-3x^2}{\sqrt{1-2x^3}}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{1}{\sqrt{1-x^2}}$.', '["$\\dfrac{x}{(1-x^2)^{3/2}}$", "$\\dfrac{-x}{(1-x^2)^{3/2}}$", "$\\dfrac{1}{(1-x^2)^{3/2}}$", "$\\dfrac{x}{\\sqrt{1-x^2}}$"]'::jsonb, 0, 'Write $y=(1-x^2)^{-1/2}$. Then $y''=-\frac12(1-x^2)^{-3/2}(-2x) = \dfrac{x}{(1-x^2)^{3/2}}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{5}{(6-x^2)^3}$.', '["$\\dfrac{30x}{(x^2-6)^4}$", "$\\dfrac{30x}{(6-x^2)^4}$", "$\\dfrac{-30x}{(6-x^2)^4}$", "$\\dfrac{15x}{(6-x^2)^4}$"]'::jsonb, 0, 'Write $y = 5(6-x^2)^{-3}$. Then $y'' = -15(6-x^2)^{-4}\cdot(-2x) = \dfrac{30x}{(6-x^2)^4} = \dfrac{30x}{(x^2-6)^4}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sqrt{x}\,(2x+1)^2$.', '["$\\dfrac{(2x+1)(10x+1)}{2\\sqrt{x}}$", "$\\dfrac{(2x+1)^2}{2\\sqrt{x}}$", "$4\\sqrt{x}(2x+1)$", "$\\dfrac{(2x+1)(10x-1)}{2\\sqrt{x}}$"]'::jsonb, 0, 'By the product and chain rules, $y'' = \sqrt{x}\cdot 4(2x+1) + (2x+1)^2\cdot\frac{1}{2\sqrt{x}}$, which combines to $\dfrac{(2x+1)(10x+1)}{2\sqrt{x}}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = x^3\sqrt{3-2x+4x^2}$.', '["$\\dfrac{x^2(16x^2-7x+9)}{\\sqrt{4x^2-2x+3}}$", "$\\dfrac{x^2(16x^2+7x+9)}{\\sqrt{4x^2-2x+3}}$", "$3x^2\\sqrt{4x^2-2x+3}$", "$\\dfrac{x^3(8x-2)}{2\\sqrt{4x^2-2x+3}}$"]'::jsonb, 0, 'By the product and chain rules, $y'' = 3x^2\sqrt{3-2x+4x^2} + x^3\cdot\dfrac{8x-2}{2\sqrt{3-2x+4x^2}}$, which simplifies to $\dfrac{x^2(16x^2-7x+9)}{\sqrt{4x^2-2x+3}}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{(1+3x^2)^{2/3}}{x}$.', '["$\\dfrac{x^2-1}{x^2(3x^2+1)^{1/3}}$", "$\\dfrac{x^2+1}{x^2(3x^2+1)^{1/3}}$", "$\\dfrac{4x}{(3x^2+1)^{1/3}}$", "$\\dfrac{x^2-1}{x(3x^2+1)^{1/3}}$"]'::jsonb, 0, 'By the quotient and chain rules, $y'' = \dfrac{x\cdot\frac{4x}{(1+3x^2)^{1/3}} - (1+3x^2)^{2/3}}{x^2}$, which simplifies to $\dfrac{x^2-1}{x^2(3x^2+1)^{1/3}}$.', 'The Chain Rule', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = (x^2-1)\cos 4x$.', '["$2x\\cos4x - 4(x^2-1)\\sin4x$", "$2x\\cos4x + 4(x^2-1)\\sin4x$", "$-2x\\sin4x$", "$2x\\cos4x-4\\sin4x$"]'::jsonb, 0, 'By the product rule, $y'' = 2x\cos4x + (x^2-1)(-4\sin4x) = 2x\cos4x - 4(x^2-1)\sin4x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = x\cos x$.', '["$\\cos x - x\\sin x$", "$\\cos x + x\\sin x$", "$-x\\sin x$", "$\\sin x - x\\cos x$"]'::jsonb, 0, 'By the product rule, $y'' = 1\cdot\cos x + x\cdot(-\sin x) = \cos x - x\sin x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Differentiate $f(x) = e^x\cos x$ with respect to $x$.', '["$e^x(\\cos x - \\sin x)$", "$e^x(\\cos x + \\sin x)$", "$-e^x\\sin x$", "$e^x\\cos x$"]'::jsonb, 0, 'By the product rule, $f''(x) = e^x\cos x + e^x(-\sin x) = e^x(\cos x-\sin x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Differentiate $f(x) = e^x\sin x$ with respect to $x$.', '["$e^x(\\sin x + \\cos x)$", "$e^x(\\sin x - \\cos x)$", "$e^x\\cos x$", "$-e^x\\cos x$"]'::jsonb, 0, 'By the product rule, $f''(x) = e^x\sin x + e^x\cos x = e^x(\sin x+\cos x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sin^7 x\cos x$.', '["$7\\sin^6x\\cos^2x - \\sin^8x$", "$7\\sin^6x\\cos^2x + \\sin^8x$", "$7\\sin^6x\\cos x$", "$\\sin^7x\\cos x - \\sin^8x$"]'::jsonb, 0, 'By the product rule, $y'' = 7\sin^6x\cos x\cdot\cos x + \sin^7x\cdot(-\sin x) = 7\sin^6x\cos^2x - \sin^8x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = x^3\cos x$.', '["$x^2(3\\cos x - x\\sin x)$", "$x^2(3\\cos x + x\\sin x)$", "$3x^2\\cos x$", "$-x^3\\sin x$"]'::jsonb, 0, 'By the product rule, $y'' = 3x^2\cos x + x^3(-\sin x) = x^2(3\cos x - x\sin x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = e^{-3x}\cos 3x$.', '["$-3e^{-3x}(\\cos3x+\\sin3x)$", "$3e^{-3x}(\\cos3x+\\sin3x)$", "$-3e^{-3x}(\\cos3x-\\sin3x)$", "$-e^{-3x}\\sin3x$"]'::jsonb, 0, 'By the product rule, $y'' = -3e^{-3x}\cos3x + e^{-3x}(-3\sin3x) = -3e^{-3x}(\cos3x+\sin3x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = 2e^{-2x}\cos 3x$.', '["$-e^{-2x}(4\\cos3x+6\\sin3x)$", "$e^{-2x}(4\\cos3x+6\\sin3x)$", "$-4e^{-2x}\\cos3x$", "$-e^{-2x}(4\\cos3x-6\\sin3x)$"]'::jsonb, 0, 'By the product rule, $y'' = -4e^{-2x}\cos3x + 2e^{-2x}(-3\sin3x) = -e^{-2x}(4\cos3x+6\sin3x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = x^2\ln x$.', '["$x(2\\ln x + 1)$", "$x(2\\ln x - 1)$", "$2x\\ln x$", "$x\\ln x$"]'::jsonb, 0, 'By the product rule, $y'' = 2x\ln x + x^2\cdot\frac1x = 2x\ln x + x = x(2\ln x+1)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = x\cos 2x$.', '["$\\cos2x - 2x\\sin2x$", "$\\cos2x + 2x\\sin2x$", "$-2x\\sin2x$", "$2\\cos2x - x\\sin2x$"]'::jsonb, 0, 'By the product rule, $y'' = \cos2x + x(-2\sin2x) = \cos2x - 2x\sin2x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = e^{2x}\cos x$.', '["$e^{2x}(2\\cos x - \\sin x)$", "$e^{2x}(2\\cos x + \\sin x)$", "$2e^{2x}\\cos x$", "$-e^{2x}\\sin x$"]'::jsonb, 0, 'By the product rule, $y'' = 2e^{2x}\cos x + e^{2x}(-\sin x) = e^{2x}(2\cos x-\sin x)$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{1}{\sin x}$.', '["$-\\dfrac{\\cos x}{\\sin^2 x}$", "$\\dfrac{\\cos x}{\\sin^2 x}$", "$-\\dfrac{1}{\\cos x}$", "$\\dfrac{-1}{\\sin^2x}$"]'::jsonb, 0, 'By the quotient rule, $y'' = \dfrac{\sin x\cdot0 - 1\cdot\cos x}{\sin^2x} = -\dfrac{\cos x}{\sin^2x}$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{x+1}{x-1}$.', '["$\\dfrac{-2}{(x-1)^2}$", "$\\dfrac{2}{(x-1)^2}$", "$\\dfrac{-1}{(x-1)^2}$", "$\\dfrac{2}{(x+1)^2}$"]'::jsonb, 0, 'By the quotient rule, $y'' = \dfrac{(x-1)(1)-(x+1)(1)}{(x-1)^2} = \dfrac{-2}{(x-1)^2}$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{x-2}{x+1}$.', '["$\\dfrac{3}{(x+1)^2}$", "$\\dfrac{-3}{(x+1)^2}$", "$\\dfrac{1}{(x+1)^2}$", "$\\dfrac{3}{(x-2)^2}$"]'::jsonb, 0, 'By the quotient rule, $y'' = \dfrac{(x+1)(1)-(x-2)(1)}{(x+1)^2} = \dfrac{3}{(x+1)^2}$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \dfrac{x}{1-x}$.', '["$\\dfrac{1}{(1-x)^2}$", "$\\dfrac{-1}{(1-x)^2}$", "$\\dfrac{1}{(x-1)}$", "$\\dfrac{2}{(1-x)^2}$"]'::jsonb, 0, 'By the quotient rule, $y'' = \dfrac{(1-x)(1)-x(-1)}{(1-x)^2} = \dfrac{1}{(1-x)^2}$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Using the quotient rule, find $\dfrac{dy}{dx}$ if $y = \tan x$.', '["$\\sec^2 x$", "$-\\csc^2x$", "$\\sec x\\tan x$", "$\\tan^2x$"]'::jsonb, 0, 'Writing $\tan x=\frac{\sin x}{\cos x}$ and applying the quotient rule, $y'' = \dfrac{\cos x\cos x-\sin x(-\sin x)}{\cos^2x} = \dfrac{\cos^2x+\sin^2x}{\cos^2x} = \sec^2x$.', 'Rules of Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x^2 - xy + y^2 = 7$, find $\dfrac{dy}{dx}$.', '["$\\dfrac{2x-y}{x-2y}$", "$\\dfrac{y-2x}{x-2y}$", "$\\dfrac{2x-y}{2y-x}$", "$\\dfrac{2x+y}{x+2y}$"]'::jsonb, 0, 'Differentiating implicitly: $2x - (y+xy'') + 2yy'' = 0$. Collecting the $y''$ terms, $y''(2y-x) = y-2x$, so $y'' = \dfrac{2x-y}{x-2y}$.', 'Implicit Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x^3+y^3 = 6xy$, find $\dfrac{dy}{dx}$.', '["$\\dfrac{2y-x^2}{y^2-2x}$", "$\\dfrac{x^2-2y}{2x-y^2}$", "$\\dfrac{x^2-2y}{y^2-2x}$", "$\\dfrac{2y-x^2}{2x-y^2}$"]'::jsonb, 0, 'Differentiating implicitly: $3x^2+3y^2y'' = 6y+6xy''$. Collecting $y''$ terms, $y''(3y^2-6x)=6y-3x^2$, so $y'' = \dfrac{6y-3x^2}{3y^2-6x} = \dfrac{2y-x^2}{y^2-2x}$.', 'Implicit Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\sin(xy) = x+y$, find $\dfrac{dy}{dx}$.', '["$\\dfrac{1-y\\cos(xy)}{x\\cos(xy)-1}$", "$\\dfrac{1+y\\cos(xy)}{x\\cos(xy)-1}$", "$\\dfrac{y\\cos(xy)-1}{1-x\\cos(xy)}$", "$\\dfrac{\\cos(xy)}{1-x}$"]'::jsonb, 0, 'Differentiating implicitly: $\cos(xy)(y+xy'') = 1+y''$. Collecting $y''$ terms, $y''(x\cos(xy)-1) = 1-y\cos(xy)$, so $y'' = \dfrac{1-y\cos(xy)}{x\cos(xy)-1}$.', 'Implicit Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x^2y+y^3 = 4$, find $\dfrac{dy}{dx}$.', '["$\\dfrac{-2xy}{x^2+3y^2}$", "$\\dfrac{2xy}{x^2+3y^2}$", "$\\dfrac{-2xy}{3y^2-x^2}$", "$\\dfrac{-x^2}{2xy+3y^2}$"]'::jsonb, 0, 'Differentiating implicitly: $2xy+x^2y''+3y^2y'' = 0$. Collecting $y''$ terms, $y''(x^2+3y^2) = -2xy$, so $y'' = \dfrac{-2xy}{x^2+3y^2}$.', 'Implicit Differentiation', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{d^2y}{dx^2}$ if $y = x^4-3x^2+2x$.', '["$12x^2-6$", "$4x^3-6x+2$", "$12x^2-6x$", "$24x$"]'::jsonb, 0, 'First, $y''=4x^3-6x+2$. Differentiating again, $y'''' = 12x^2-6$.', 'Higher Order Derivatives', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the fourth derivative of $y = \sin 2x$.', '["$16\\sin 2x$", "$-16\\sin2x$", "$16\\cos2x$", "$8\\sin2x$"]'::jsonb, 0, 'Each differentiation multiplies by $2$ and rotates $\sin\to\cos\to-\sin\to-\cos\to\sin$. After four derivatives, $y^{(4)}=2^4\sin2x=16\sin2x$.', 'Higher Order Derivatives', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{d^2y}{dx^2}$ if $y = x^2e^x$.', '["$(x^2+4x+2)e^x$", "$(x^2+2x+2)e^x$", "$(x^2+4x)e^x$", "$2e^x$"]'::jsonb, 0, 'First, $y'' = 2xe^x+x^2e^x = (x^2+2x)e^x$. Differentiating again using the product rule gives $y'''' = (2x+2)e^x+(x^2+2x)e^x = (x^2+4x+2)e^x$.', 'Higher Order Derivatives', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = 10^{3x}$.', '["$3\\ln(10)\\cdot 10^{3x}$", "$3\\cdot 10^{3x}$", "$10^{3x}\\ln10$", "$3x\\cdot10^{3x-1}$"]'::jsonb, 0, 'Taking $\ln$ of both sides, $\ln y = 3x\ln10$. Differentiating implicitly, $\frac{y''}{y}=3\ln10$, so $y''=3\ln(10)\cdot10^{3x}$.', 'The Exponential Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = 5^{x}$.', '["$5^x\\ln5$", "$5^x$", "$x5^{x-1}$", "$5^x\\ln x$"]'::jsonb, 0, 'Taking $\ln$ of both sides, $\ln y = x\ln5$. Differentiating implicitly, $\frac{y''}{y}=\ln5$, so $y''=5^x\ln5$.', 'The Exponential Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = 3^{2x}$.', '["$2\\ln(3)\\cdot3^{2x}$", "$2\\cdot3^{2x}$", "$3^{2x}\\ln3$", "$2x\\cdot3^{2x-1}$"]'::jsonb, 0, 'Taking $\ln$ of both sides, $\ln y=2x\ln3$. Differentiating implicitly, $\frac{y''}{y}=2\ln3$, so $y''=2\ln(3)\cdot3^{2x}$.', 'The Exponential Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = x^x$ (for $x>0$).', '["$x^x(\\ln x+1)$", "$x\\cdot x^{x-1}$", "$x^x\\ln x$", "$x^x$"]'::jsonb, 0, 'Taking $\ln$ of both sides, $\ln y=x\ln x$. Differentiating implicitly, $\frac{y''}{y}=\ln x+1$, so $y''=x^x(\ln x+1)$.', 'The Exponential Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \ln(1-2x^2)$.', '["$\\dfrac{-4x}{1-2x^2}$", "$\\dfrac{4x}{1-2x^2}$", "$\\dfrac{-4x}{2x^2-1}$", "$\\dfrac{-4}{1-2x^2}$"]'::jsonb, 0, 'By the chain rule, $y''=\dfrac{-4x}{1-2x^2}$.', 'The Natural Logarithmic Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \ln(2\cos 3x+1)$.', '["$\\dfrac{-6\\sin3x}{2\\cos3x+1}$", "$\\dfrac{6\\sin3x}{2\\cos3x+1}$", "$\\dfrac{-2\\sin3x}{2\\cos3x+1}$", "$\\dfrac{-6\\cos3x}{2\\cos3x+1}$"]'::jsonb, 0, 'By the chain rule, $y'' = \dfrac{1}{2\cos3x+1}\cdot(-6\sin3x) = \dfrac{-6\sin3x}{2\cos3x+1}$.', 'The Natural Logarithmic Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \log_{10}(1-2x^2)$.', '["$\\dfrac{4x}{(2x^2-1)\\ln10}$", "$\\dfrac{-4x}{(1-2x^2)\\ln10}$", "$\\dfrac{4x}{1-2x^2}$", "$\\dfrac{4x\\ln10}{1-2x^2}$"]'::jsonb, 0, 'Using $\log_{10}u = \dfrac{\ln u}{\ln10}$, $y'' = \dfrac{1}{(1-2x^2)\ln10}\cdot(-4x) = \dfrac{4x}{(2x^2-1)\ln10}$.', 'Logarithms and Exponentials to Other Bases', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \log_3(1+x^2)$.', '["$\\dfrac{2x}{(x^2+1)\\ln3}$", "$\\dfrac{2x}{x^2+1}$", "$\\dfrac{1}{(x^2+1)\\ln3}$", "$\\dfrac{2x\\ln3}{x^2+1}$"]'::jsonb, 0, 'Using $\log_3u = \dfrac{\ln u}{\ln3}$, $y'' = \dfrac{1}{(1+x^2)\ln3}\cdot 2x = \dfrac{2x}{(x^2+1)\ln3}$.', 'Logarithms and Exponentials to Other Bases', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x=t^2-1$ and $y=t^2+t$, find $\dfrac{dy}{dx}$ in terms of $t$.', '["$1+\\dfrac{1}{2t}$", "$1-\\dfrac{1}{2t}$", "$2t+1$", "$\\dfrac{1}{2t}$"]'::jsonb, 0, '$\dfrac{dx}{dt}=2t$ and $\dfrac{dy}{dt}=2t+1$, so $\dfrac{dy}{dx} = \dfrac{2t+1}{2t} = 1+\dfrac{1}{2t}$.', 'Derivatives of Functions Expressed Parametrically', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x=t^2-1$ and $y=t^2+t$, find $\dfrac{dy}{dx}$ at $t=\dfrac12$.', '["$2$", "$1$", "$\\dfrac12$", "$3$"]'::jsonb, 0, 'From $\dfrac{dy}{dx}=1+\dfrac{1}{2t}$, substituting $t=\frac12$ gives $1+\dfrac{1}{1}=2$.', 'Derivatives of Functions Expressed Parametrically', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $y=2t+1$ and $x=2-t^2$, find $\dfrac{dy}{dx}$ in terms of $t$.', '["$-\\dfrac{1}{t}$", "$\\dfrac{1}{t}$", "$-2t$", "$-\\dfrac{1}{2t}$"]'::jsonb, 0, '$\dfrac{dx}{dt}=-2t$ and $\dfrac{dy}{dt}=2$, so $\dfrac{dy}{dx} = \dfrac{2}{-2t} = -\dfrac1t$.', 'Derivatives of Functions Expressed Parametrically', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x=1-t^2$ and $y=2t-1$, find $\dfrac{dy}{dx}$ in terms of $t$.', '["$-\\dfrac{1}{t}$", "$\\dfrac{1}{t}$", "$2t$", "$-2t$"]'::jsonb, 0, '$\dfrac{dx}{dt}=-2t$ and $\dfrac{dy}{dt}=2$, so $\dfrac{dy}{dx} = \dfrac{2}{-2t} = -\dfrac1t$.', 'Derivatives of Functions Expressed Parametrically', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \tan^{-1}(2x)$.', '["$\\dfrac{2}{1+4x^2}$", "$\\dfrac{1}{1+4x^2}$", "$\\dfrac{2}{1-4x^2}$", "$\\dfrac{4x}{1+4x^2}$"]'::jsonb, 0, 'Using $\dfrac{d}{dx}\tan^{-1}u = \dfrac{u''}{1+u^2}$ with $u=2x$: $y'' = \dfrac{2}{1+4x^2}$.', 'Inverse Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \cos^{-1}(3x)$.', '["$\\dfrac{-3}{\\sqrt{1-9x^2}}$", "$\\dfrac{3}{\\sqrt{1-9x^2}}$", "$\\dfrac{-1}{\\sqrt{1-9x^2}}$", "$\\dfrac{-3}{1-9x^2}$"]'::jsonb, 0, 'Using $\dfrac{d}{dx}\cos^{-1}u = \dfrac{-u''}{\sqrt{1-u^2}}$ with $u=3x$: $y'' = \dfrac{-3}{\sqrt{1-9x^2}}$.', 'Inverse Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\dfrac{dy}{dx}$ if $y = \sin^{-1}(2x)$.', '["$\\dfrac{2}{\\sqrt{1-4x^2}}$", "$\\dfrac{1}{\\sqrt{1-4x^2}}$", "$\\dfrac{-2}{\\sqrt{1-4x^2}}$", "$\\dfrac{2}{1-4x^2}$"]'::jsonb, 0, 'Using $\dfrac{d}{dx}\sin^{-1}u = \dfrac{u''}{\sqrt{1-u^2}}$ with $u=2x$: $y'' = \dfrac{2}{\sqrt{1-4x^2}}$.', 'Inverse Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $y=\sin^{-1}\left(\dfrac{x}{3}\right)$, find $\dfrac{dy}{dx}$.', '["$\\dfrac{1}{\\sqrt{9-x^2}}$", "$\\dfrac{1}{3\\sqrt{1-x^2}}$", "$\\dfrac{3}{\\sqrt{9-x^2}}$", "$\\dfrac{1}{\\sqrt{9+x^2}}$"]'::jsonb, 0, 'For $y=\sin^{-1}(x/a)$ the standard result is $y''=\dfrac{1}{\sqrt{a^2-x^2}}$; with $a=3$, $y''=\dfrac{1}{\sqrt{9-x^2}}$.', 'Inverse Trigonometric Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to $y = x^3-2x^2-4x+4$ at the point where $x=1$.', '["$5x+y-4=0$", "$5x-y-4=0$", "$5x+y+4=0$", "$x+5y+4=0$"]'::jsonb, 0, 'At $x=1$, $y=1-2-4+4=-1$ and $y''=3x^2-4x-4$ gives slope $3-4-4=-5$. The tangent is $y-(-1)=-5(x-1)$, i.e. $5x+y-4=0$.', 'Tangents and Normals', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the normal to the curve $y=x^2$ at the point $(1,1)$.', '["$x+2y-3=0$", "$2x-y-1=0$", "$x-2y+1=0$", "$2x+y-3=0$"]'::jsonb, 0, 'At $x=1$, $y''=2x=2$, so the tangent slope is $2$ and the normal slope is $-\frac12$. The normal is $y-1=-\frac12(x-1)$, i.e. $x+2y-3=0$.', 'Tangents and Normals', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to $y=x^2-3x+2$ at the point where $x=2$.', '["$x-y-2=0$", "$x+y-2=0$", "$x-y+2=0$", "$2x-y-4=0$"]'::jsonb, 0, 'At $x=2$, $y=4-6+2=0$ and $y''=2x-3=1$. The tangent is $y-0=1(x-2)$, i.e. $x-y-2=0$.', 'Tangents and Normals', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the critical points of $f(x) = x^3-3x^2+2$.', '["$x=0$ and $x=2$", "$x=1$ and $x=-1$", "$x=0$ only", "$x=3$ and $x=0$"]'::jsonb, 0, '$f''(x)=3x^2-6x=3x(x-2)$, which is zero when $x=0$ or $x=2$.', 'Extrema of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Using the second derivative test, classify the critical point $x=0$ of $f(x)=x^3-3x^2+2$.', '["Local maximum", "Local minimum", "Point of inflection", "Not an extremum"]'::jsonb, 0, '$f''''(x)=6x-6$, so $f''''(0)=-6<0$, which means $x=0$ is a local maximum by the second derivative test.', 'The Second Derivative Test for Extremum', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Using the second derivative test, classify the critical point $x=2$ of $f(x)=x^3-3x^2+2$.', '["Local minimum", "Local maximum", "Point of inflection", "Not an extremum"]'::jsonb, 0, '$f''''(x)=6x-6$, so $f''''(2)=6>0$, which means $x=2$ is a local minimum by the second derivative test.', 'The Second Derivative Test for Extremum', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the critical points of $f(x) = 4x^3-5x^2+1$.', '["$x=0$ and $x=\\dfrac56$", "$x=0$ and $x=\\dfrac65$", "$x=\\dfrac56$ only", "$x=0$ and $x=1$"]'::jsonb, 0, '$f''(x)=12x^2-10x = 2x(6x-5)$, which is zero when $x=0$ or $x=\frac56$.', 'Extrema of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The function $f(x)=4x^3-5x^2+1$ has a local minimum value of', '["$-\\dfrac{17}{108}$", "$1$", "$\\dfrac{17}{108}$", "$0$"]'::jsonb, 0, 'The critical points are $x=0$ and $x=\frac56$. Since $f''''(x)=24x-10$, $f''''(5/6)=10>0$, so $x=\frac56$ gives a local minimum, with value $f(5/6)=-\frac{17}{108}$.', 'Maxima and Minima', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the points of inflection of $f(x) = x^3-3x+2$.', '["$x=0$", "$x=1$", "$x=-1$", "$x=1$ and $x=-1$"]'::jsonb, 0, 'A point of inflection requires $f''''(x)=0$ with a sign change. Here $f''''(x)=6x$, which is zero (and changes sign) only at $x=0$.', 'Concavity and Points of Inflection', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'On which interval is $f(x)=x^3-3x+2$ increasing?', '["$x<-1$ or $x>1$", "$-1<x<1$", "$x>0$ only", "$x<0$ only"]'::jsonb, 0, '$f''(x)=3x^2-3=3(x-1)(x+1)$, which is positive when $x<-1$ or $x>1$, so $f$ is increasing on these intervals.', 'Monotonicity of a Function', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The area of a circular oil spill is increasing because its radius is growing at a constant rate of $3\text{ m/min}$. How fast is the area increasing (in m$^2$/min) at the instant the radius is $5$ m?', '["$30\\pi$", "$15\\pi$", "$25\\pi$", "$9\\pi$"]'::jsonb, 0, '$A=\pi r^2$, so $\dfrac{dA}{dt}=2\pi r\dfrac{dr}{dt}$. With $r=5$ and $\dfrac{dr}{dt}=3$, $\dfrac{dA}{dt}=2\pi(5)(3)=30\pi$.', 'Velocity and Acceleration', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A spherical balloon is being inflated so that its radius increases at a constant rate of $2\text{ cm/s}$. How fast is its volume increasing (in cm$^3$/s) when the radius is $3$ cm?', '["$72\\pi$", "$36\\pi$", "$24\\pi$", "$108\\pi$"]'::jsonb, 0, '$V=\frac43\pi r^3$, so $\dfrac{dV}{dt}=4\pi r^2\dfrac{dr}{dt}$. With $r=3$ and $\dfrac{dr}{dt}=2$, $\dfrac{dV}{dt}=4\pi(9)(2)=72\pi$.', 'Velocity and Acceleration', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A $13$-metre ladder leans against a vertical wall. The bottom is being pulled away from the wall at $2\text{ m/s}$. How fast is the top of the ladder sliding down the wall (in m/s) at the instant the bottom is $5$ m from the wall?', '["$\\dfrac{5}{6}$", "$\\dfrac{6}{5}$", "$\\dfrac{5}{12}$", "$2$"]'::jsonb, 0, 'If $x$ is the base distance and $y$ the height, $x^2+y^2=169$. At $x=5$, $y=12$. Differentiating, $2x\frac{dx}{dt}+2y\frac{dy}{dt}=0$, so $\frac{dy}{dt} = -\frac{x}{y}\frac{dx}{dt} = -\frac{5}{12}(2) = -\frac{5}{6}$; the top slides down at $\frac56$ m/s.', 'Velocity and Acceleration', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The displacement of a particle moving along a line is given by $s(t) = -16t^2+50t+400$. Find its initial velocity ($v(0)$).', '["$50$", "$400$", "$-32$", "$0$"]'::jsonb, 0, 'Velocity is $v(t)=s''(t) = -32t+50$. At $t=0$, $v(0)=50$.', 'Velocity and Acceleration', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The displacement of a particle moving along a line is given by $s(t) = -16t^2+50t+400$. Find its acceleration.', '["$-32$ (constant)", "$-16$ (constant)", "$50-32t$", "$0$"]'::jsonb, 0, 'Velocity is $v(t)=-32t+50$, and acceleration is $a(t)=v''(t) = -32$, a constant.', 'Velocity and Acceleration', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int (4x^3+5x^2-2x+7)\,dx$.', '["$x^4+\\dfrac{5x^3}{3}-x^2+7x+C$", "$x^4+5x^3-x^2+7x+C$", "$12x^2+10x-2+C$", "$x^4+\\dfrac{5x^3}{3}+x^2+7x+C$"]'::jsonb, 0, 'Integrate term by term using the power rule $\int x^n\,dx=\frac{x^{n+1}}{n+1}+C$: $\int4x^3dx=x^4$, $\int5x^2dx=\frac{5x^3}{3}$, $\int-2x\,dx=-x^2$, $\int7\,dx=7x$.', 'Antiderivatives of Some Elementary Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{x^2+3}{x}\,dx$ for $x>0$.', '["$\\dfrac{x^2}{2}+3\\ln x+C$", "$\\dfrac{x^2}{2}+3\\ln x^2+C$", "$2x+3\\ln x+C$", "$\\dfrac{x^2}{2}-3\\ln x+C$"]'::jsonb, 0, 'Split the fraction: $\frac{x^2+3}{x}=x+\frac3x$. Then $\int\left(x+\frac3x\right)dx = \frac{x^2}{2}+3\ln x+C$ (for $x>0$).', 'Antiderivatives of Some Elementary Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int (2x+1)^5\,dx$ by expanding the integrand as a polynomial in $x$.', '["$\\dfrac{16x^6}{3}+16x^5+20x^4+\\dfrac{40x^3}{3}+5x^2+x+C$", "$\\dfrac{(2x+1)^6}{6}+C$", "$\\dfrac{16x^6}{3}+16x^5+20x^4+\\dfrac{40x^3}{3}+5x^2+C$", "$16x^6+16x^5+20x^4+C$"]'::jsonb, 0, 'Expanding $(2x+1)^5$ into a polynomial and integrating term by term gives $\dfrac{16x^6}{3}+16x^5+20x^4+\dfrac{40x^3}{3}+5x^2+x+C$. (Substitution would give the equivalent, faster answer $\frac{(2x+1)^6}{12}+C$.)', 'Antiderivatives of Some Elementary Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int (4x-7)^3\,dx$.', '["$\\dfrac{(4x-7)^4}{16}+C$", "$\\dfrac{(4x-7)^4}{4}+C$", "$(4x-7)^4+C$", "$4(4x-7)^4+C$"]'::jsonb, 0, 'Let $u=4x-7$, so $du=4\,dx$. Then $\int u^3\,\frac{du}{4} = \frac{u^4}{16}+C = \frac{(4x-7)^4}{16}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \cos(3x)\,dx$.', '["$\\dfrac{\\sin 3x}{3}+C$", "$\\sin3x+C$", "$-\\dfrac{\\sin3x}{3}+C$", "$3\\sin3x+C$"]'::jsonb, 0, 'Let $u=3x$, so $du=3\,dx$. Then $\int\cos u\,\frac{du}{3} = \frac{\sin u}{3}+C = \frac{\sin3x}{3}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int e^{3x+2}\,dx$.', '["$\\dfrac{e^{3x+2}}{3}+C$", "$e^{3x+2}+C$", "$3e^{3x+2}+C$", "$\\dfrac{e^{3x+2}}{2}+C$"]'::jsonb, 0, 'Let $u=3x+2$, so $du=3\,dx$. Then $\int e^u\,\frac{du}{3} = \frac{e^u}{3}+C = \frac{e^{3x+2}}{3}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \sqrt{3-4x}\,dx$.', '["$-\\dfrac{(3-4x)^{3/2}}{6}+C$", "$\\dfrac{(3-4x)^{3/2}}{6}+C$", "$-\\dfrac{2}{3}(3-4x)^{3/2}+C$", "$-\\dfrac{(3-4x)^{3/2}}{4}+C$"]'::jsonb, 0, 'Let $u=3-4x$, so $du=-4\,dx$. Then $\int\sqrt u\left(-\frac{du}{4}\right) = -\frac14\cdot\frac{2}{3}u^{3/2}+C = -\frac{(3-4x)^{3/2}}{6}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x\sqrt{1+x^2}\,dx$.', '["$\\dfrac{(1+x^2)^{3/2}}{3}+C$", "$\\dfrac{2(1+x^2)^{3/2}}{3}+C$", "$\\dfrac{x^2\\sqrt{1+x^2}}{3}+C$", "$(1+x^2)^{3/2}+C$"]'::jsonb, 0, 'Let $u=1+x^2$, so $du=2x\,dx$. Then $\int\sqrt u\,\frac{du}{2} = \frac13 u^{3/2}+C = \frac{(1+x^2)^{3/2}}{3}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{x}{\sqrt{4-x^2}}\,dx$.', '["$-\\sqrt{4-x^2}+C$", "$\\sqrt{4-x^2}+C$", "$-\\dfrac12\\sqrt{4-x^2}+C$", "$\\dfrac{x^2}{2\\sqrt{4-x^2}}+C$"]'::jsonb, 0, 'Let $u=4-x^2$, so $du=-2x\,dx$. Then $\int\frac{1}{\sqrt u}\left(-\frac{du}{2}\right) = -\sqrt u+C = -\sqrt{4-x^2}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \cos^2 x\,dx$.', '["$\\dfrac{x}{2}+\\dfrac{\\sin2x}{4}+C$", "$\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$", "$\\dfrac{\\sin2x}{4}+C$", "$x+\\sin2x+C$"]'::jsonb, 0, 'Using $\cos^2x=\frac{1+\cos2x}{2}$: $\int\cos^2x\,dx = \frac{x}{2}+\frac{\sin2x}{4}+C$.', 'Antiderivatives of Some Elementary Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \sin^2 x\,dx$.', '["$\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$", "$\\dfrac{x}{2}+\\dfrac{\\sin2x}{4}+C$", "$-\\dfrac{\\sin2x}{4}+C$", "$x-\\sin2x+C$"]'::jsonb, 0, 'Using $\sin^2x=\frac{1-\cos2x}{2}$: $\int\sin^2x\,dx = \frac{x}{2}-\frac{\sin2x}{4}+C$.', 'Antiderivatives of Some Elementary Functions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \sin^3 x\,dx$.', '["$\\dfrac{\\cos^3x}{3}-\\cos x+C$", "$-\\dfrac{\\cos^3x}{3}+\\cos x+C$", "$\\cos x - \\dfrac{\\cos^3x}{3}+C$", "$-\\cos x-\\dfrac{\\cos^3x}{3}+C$"]'::jsonb, 0, 'Write $\sin^3x=\sin x(1-\cos^2x)$ and substitute $u=\cos x$: $\int(u^2-1)\,du = \frac{u^3}{3}-u+C = \frac{\cos^3x}{3}-\cos x+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \cos^3 x\,dx$.', '["$\\sin x-\\dfrac{\\sin^3x}{3}+C$", "$\\dfrac{\\sin^3x}{3}-\\sin x+C$", "$\\sin x+\\dfrac{\\sin^3x}{3}+C$", "$-\\sin x+\\dfrac{\\sin^3x}{3}+C$"]'::jsonb, 0, 'Write $\cos^3x=\cos x(1-\sin^2x)$ and substitute $u=\sin x$: $\int(1-u^2)\,du = u-\frac{u^3}{3}+C = \sin x-\frac{\sin^3x}{3}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \sin^5 x\,dx$.', '["$-\\cos x+\\dfrac{2\\cos^3x}{3}-\\dfrac{\\cos^5x}{5}+C$", "$-\\cos x-\\dfrac{2\\cos^3x}{3}+\\dfrac{\\cos^5x}{5}+C$", "$\\cos x-\\dfrac{2\\cos^3x}{3}+\\dfrac{\\cos^5x}{5}+C$", "$-\\dfrac{\\cos^5x}{5}+C$"]'::jsonb, 0, 'Write $\sin^5x = \sin x(1-\cos^2x)^2$ and substitute $u=\cos x$: $-\int(1-u^2)^2\,du = -\int(1-2u^2+u^4)\,du = -u+\frac{2u^3}{3}-\frac{u^5}{5}+C$, giving $-\cos x+\frac{2\cos^3x}{3}-\frac{\cos^5x}{5}+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{3x^2+4x}{x^3+2x^2+7}\,dx$.', '["$\\ln|x^3+2x^2+7|+C$", "$\\ln|3x^2+4x|+C$", "$\\dfrac{1}{x^3+2x^2+7}+C$", "$3\\ln|x^3+2x^2+7|+C$"]'::jsonb, 0, 'The numerator is exactly the derivative of the denominator, so this has the form $\int\frac{f''(x)}{f(x)}dx = \ln|f(x)|+C = \ln|x^3+2x^2+7|+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{\sec^2x}{\tan x}\,dx$.', '["$\\ln|\\tan x|+C$", "$\\ln|\\sec x|+C$", "$\\tan x + C$", "$\\dfrac{1}{2}\\ln|\\tan x|+C$"]'::jsonb, 0, 'The numerator $\sec^2x$ is the derivative of $\tan x$, so this has the form $\int\frac{f''(x)}{f(x)}dx = \ln|\tan x|+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{2x+3}{x^2+3x+7}\,dx$.', '["$\\ln|x^2+3x+7|+C$", "$\\ln|2x+3|+C$", "$\\dfrac{2x+3}{2}\\ln|x^2+3x+7|+C$", "$2\\ln|x^2+3x+7|+C$"]'::jsonb, 0, 'The numerator is the derivative of the denominator, so $\int\frac{f''(x)}{f(x)}dx = \ln|x^2+3x+7|+C$.', 'Method of Substitution', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{1}^{2} 2x^2\,dx$.', '["$\\dfrac{14}{3}$", "$\\dfrac{7}{3}$", "$14$", "$\\dfrac{16}{3}$"]'::jsonb, 0, '$\int2x^2\,dx = \frac{2x^3}{3}$. Evaluating from $1$ to $2$: $\frac{16}{3}-\frac{2}{3} = \frac{14}{3}$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{1}^{4} \dfrac{7+\sqrt{x}}{x^2}\,dx$.', '["$\\dfrac{25}{4}$", "$\\dfrac{25}{8}$", "$\\dfrac{7}{4}$", "$\\dfrac{9}{2}$"]'::jsonb, 0, 'Split as $7x^{-2}+x^{-3/2}$, whose antiderivative is $-7x^{-1}-2x^{-1/2}$. Evaluating from $1$ to $4$: $\left(-\frac74-1\right) - \left(-7-2\right) = -\frac{11}{4}+9 = \frac{25}{4}$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{0}^{\ln 2} e^{2x}\,dx$.', '["$\\dfrac32$", "$\\dfrac12$", "$2$", "$\\ln 2$"]'::jsonb, 0, '$\int e^{2x}\,dx = \frac{e^{2x}}{2}$. Evaluating: $\frac{e^{2\ln2}}{2}-\frac{1}{2} = \frac{4}{2}-\frac12 = \frac32$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{-3}^{1} \sqrt{3+x}\,dx$.', '["$\\dfrac{16}{3}$", "$\\dfrac{8}{3}$", "$\\dfrac{32}{3}$", "$4$"]'::jsonb, 0, 'Let $u=3+x$. Then $\int\sqrt u\,du = \frac23u^{3/2}$. Evaluating from $u=0$ to $u=4$: $\frac23(8)-0=\frac{16}{3}$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{0}^{2} \dfrac{x}{x^2+1}\,dx$.', '["$\\dfrac{\\ln 5}{2}$", "$\\ln 5$", "$\\dfrac{\\ln 5}{4}$", "$\\ln 2$"]'::jsonb, 0, 'Let $u=x^2+1$, $du=2x\,dx$. Then $\int\frac{1}{2u}du = \frac12\ln u$. Evaluating from $u=1$ to $u=5$: $\frac12\ln5-\frac12\ln1 = \frac{\ln5}{2}$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{1}^{e} \dfrac{\ln x}{x}\,dx$.', '["$\\dfrac12$", "$1$", "$e$", "$0$"]'::jsonb, 0, 'Let $u=\ln x$, $du=\frac{dx}{x}$. Then $\int u\,du = \frac{u^2}{2}$. Evaluating from $u=0$ to $u=1$: $\frac12-0=\frac12$.', 'Fundamental Theorem of Integral Calculus', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x e^x\,dx$.', '["$(x-1)e^x+C$", "$(x+1)e^x+C$", "$xe^x+C$", "$e^x+C$"]'::jsonb, 0, 'Using integration by parts with $u=x$, $dv=e^x dx$: $\int xe^x\,dx = xe^x-\int e^x\,dx = xe^x-e^x+C = (x-1)e^x+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x\sin x\,dx$.', '["$-x\\cos x+\\sin x+C$", "$x\\cos x+\\sin x+C$", "$-x\\cos x-\\sin x+C$", "$x\\sin x+\\cos x+C$"]'::jsonb, 0, 'Using integration by parts with $u=x$, $dv=\sin x\,dx$: $\int x\sin x\,dx = -x\cos x+\int\cos x\,dx = -x\cos x+\sin x+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x\ln x\,dx$ (for $x>0$).', '["$\\dfrac{x^2}{2}\\ln x-\\dfrac{x^2}{4}+C$", "$\\dfrac{x^2}{2}\\ln x+\\dfrac{x^2}{4}+C$", "$x^2\\ln x-x^2+C$", "$\\dfrac{x^2}{2}\\ln x - x^2+C$"]'::jsonb, 0, 'Using integration by parts with $u=\ln x$, $dv=x\,dx$: $\int x\ln x\,dx = \frac{x^2}{2}\ln x-\int\frac{x}{2}\,dx = \frac{x^2}{2}\ln x-\frac{x^2}{4}+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x^2\ln x\,dx$ (for $x>0$).', '["$\\dfrac{x^3}{3}\\ln x-\\dfrac{x^3}{9}+C$", "$\\dfrac{x^3}{3}\\ln x+\\dfrac{x^3}{9}+C$", "$x^3\\ln x-\\dfrac{x^3}{3}+C$", "$\\dfrac{x^3}{3}\\ln x-x^3+C$"]'::jsonb, 0, 'Using integration by parts with $u=\ln x$, $dv=x^2\,dx$: $\int x^2\ln x\,dx = \frac{x^3}{3}\ln x-\int\frac{x^2}{3}\,dx = \frac{x^3}{3}\ln x-\frac{x^3}{9}+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x^2\cos x\,dx$.', '["$x^2\\sin x+2x\\cos x-2\\sin x+C$", "$x^2\\sin x-2x\\cos x+2\\sin x+C$", "$x^2\\sin x+2x\\cos x+2\\sin x+C$", "$-x^2\\sin x+2x\\cos x+2\\sin x+C$"]'::jsonb, 0, 'Apply integration by parts twice: first with $u=x^2, dv=\cos x\,dx$ to get $x^2\sin x-\int2x\sin x\,dx$, then apply it again to $\int2x\sin x\,dx=-2x\cos x+2\sin x$. Combining, the result is $x^2\sin x+2x\cos x-2\sin x+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int x^2 e^x\,dx$.', '["$(x^2-2x+2)e^x+C$", "$(x^2+2x+2)e^x+C$", "$(x^2-2x-2)e^x+C$", "$x^2e^x+C$"]'::jsonb, 0, 'Apply integration by parts twice: with $u=x^2,dv=e^x dx$ this gives $x^2e^x-2\int xe^x\,dx$, and using $\int xe^x\,dx=(x-1)e^x$ (from a previous result), the answer simplifies to $(x^2-2x+2)e^x+C$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{0}^{\pi/2} x\sin x\,dx$.', '["$1$", "$\\dfrac{\\pi}{2}$", "$0$", "$\\dfrac{\\pi}{2}-1$"]'::jsonb, 0, 'From integration by parts, $\int x\sin x\,dx=-x\cos x+\sin x$. Evaluating from $0$ to $\pi/2$: $\left(0+1\right)-\left(0+0\right)=1$.', 'Integration by Parts', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{1}{(x+1)(x+2)}\,dx$.', '["$\\ln\\left|\\dfrac{x+1}{x+2}\\right|+C$", "$\\ln|(x+1)(x+2)|+C$", "$\\ln\\left|\\dfrac{x+2}{x+1}\\right|+C$", "$\\dfrac{1}{x+1}-\\dfrac{1}{x+2}+C$"]'::jsonb, 0, 'Resolving into partial fractions, $\frac{1}{(x+1)(x+2)} = \frac{1}{x+1}-\frac{1}{x+2}$. Integrating gives $\ln|x+1|-\ln|x+2|+C = \ln\left|\frac{x+1}{x+2}\right|+C$.', 'Method of Partial Fractions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{x-1}{x(x+1)}\,dx$.', '["$2\\ln|x+1|-\\ln|x|+C$", "$\\ln|x+1|-2\\ln|x|+C$", "$2\\ln|x|-\\ln|x+1|+C$", "$\\ln|x(x+1)|+C$"]'::jsonb, 0, 'Resolving into partial fractions, $\frac{x-1}{x(x+1)}=\frac{-1}{x}+\frac{2}{x+1}$. Integrating gives $-\ln|x|+2\ln|x+1|+C$.', 'Method of Partial Fractions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{3x+5}{(x-1)(x+2)}\,dx$.', '["$\\dfrac{8}{3}\\ln|x-1|+\\dfrac{1}{3}\\ln|x+2|+C$", "$\\dfrac{1}{3}\\ln|x-1|+\\dfrac{8}{3}\\ln|x+2|+C$", "$\\dfrac83\\ln|x-1|-\\dfrac13\\ln|x+2|+C$", "$3\\ln|x-1|+5\\ln|x+2|+C$"]'::jsonb, 0, 'Resolving into partial fractions, $\frac{3x+5}{(x-1)(x+2)} = \frac{8/3}{x-1}+\frac{1/3}{x+2}$. Integrating gives $\frac83\ln|x-1|+\frac13\ln|x+2|+C$.', 'Method of Partial Fractions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int \dfrac{x+5}{x^2-x-6}\,dx$.', '["$\\dfrac{8}{5}\\ln|x-3|-\\dfrac{3}{5}\\ln|x+2|+C$", "$\\dfrac{3}{5}\\ln|x-3|-\\dfrac{8}{5}\\ln|x+2|+C$", "$\\dfrac85\\ln|x-3|+\\dfrac35\\ln|x+2|+C$", "$\\ln|x^2-x-6|+C$"]'::jsonb, 0, 'Since $x^2-x-6=(x-3)(x+2)$, resolving into partial fractions gives $\frac{x+5}{(x-3)(x+2)}=\frac{8/5}{x-3}-\frac{3/5}{x+2}$. Integrating gives $\frac85\ln|x-3|-\frac35\ln|x+2|+C$.', 'Method of Partial Fractions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by the curve $y=4x-x^2$ and the $x$-axis.', '["$\\dfrac{32}{3}$", "$\\dfrac{16}{3}$", "$16$", "$\\dfrac{64}{3}$"]'::jsonb, 0, 'The curve meets the $x$-axis where $4x-x^2=0$, i.e. $x=0$ and $x=4$. The area is $\int_0^4(4x-x^2)\,dx = \left[2x^2-\frac{x^3}{3}\right]_0^4 = 32-\frac{64}{3} = \frac{32}{3}$.', 'Areas of Plane Regions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the region enclosed between the curves $y=x^2$ and $y=x+6$.', '["$\\dfrac{125}{6}$", "$\\dfrac{125}{3}$", "$\\dfrac{25}{6}$", "$\\dfrac{27}{2}$"]'::jsonb, 0, 'The curves intersect where $x^2=x+6$, i.e. $x=-2$ and $x=3$. The area is $\int_{-2}^{3}\left[(x+6)-x^2\right]dx = \left[\frac{x^2}{2}+6x-\frac{x^3}{3}\right]_{-2}^{3} = \frac{125}{6}$.', 'Areas of Plane Regions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the total area of the region(s) enclosed between the curves $y=x^3$ and $y=x$ on the interval $[-1,1]$.', '["$\\dfrac12$", "$0$", "$\\dfrac14$", "$1$"]'::jsonb, 0, 'The curves cross at $x=-1,0,1$. On $[-1,0]$, $x^3\geq x$; on $[0,1]$, $x\geq x^3$. Each piece contributes area $\frac14$, giving a total area of $\int_{-1}^{0}(x^3-x)dx+\int_0^1(x-x^3)dx = \frac14+\frac14=\frac12$.', 'Areas of Plane Regions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the region enclosed between the curves $y=2x$ and $y=x^2$.', '["$\\dfrac43$", "$\\dfrac83$", "$2$", "$4$"]'::jsonb, 0, 'The curves intersect where $2x=x^2$, i.e. $x=0$ and $x=2$. The area is $\int_0^2(2x-x^2)\,dx = \left[x^2-\frac{x^3}{3}\right]_0^2 = 4-\frac83 = \frac43$.', 'Areas of Plane Regions', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A region under the curve $y=x^2$ on $[0,2]$ is approximated by a right-endpoint Riemann sum with $n=4$ equal subintervals. What is the width of each subinterval?', '["$0.5$", "$2$", "$4$", "$0.25$"]'::jsonb, 0, 'The interval $[0,2]$ has length $2$, divided into $n=4$ equal parts, so each subinterval has width $\Delta x = \frac{2}{4}=0.5$.', 'Areas and Riemann Sums', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Using a right-endpoint Riemann sum with $n=4$ equal subintervals on $[0,2]$, estimate $\displaystyle\int_0^2 x^2\,dx$.', '["$3.75$", "$2.67$", "$4$", "$3$"]'::jsonb, 0, 'With $\Delta x=0.5$, the right endpoints are $0.5,1,1.5,2$. The sum is $0.5\left(0.5^2+1^2+1.5^2+2^2\right) = 0.5(0.25+1+2.25+4)=0.5(7.5)=3.75$. (The exact value $\int_0^2x^2dx=\frac83\approx2.67$ is approached as $n\to\infty$.)', 'Areas and Riemann Sums', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid generated when the region under $y=\sqrt{x}$ on $[0,4]$ is revolved about the $x$-axis.', '["$8\\pi$", "$4\\pi$", "$16\\pi$", "$\\dfrac{8\\pi}{3}$"]'::jsonb, 0, 'By the disc method, $V=\pi\int_0^4 (\sqrt x)^2\,dx = \pi\int_0^4 x\,dx = \pi\left[\frac{x^2}{2}\right]_0^4 = 8\pi$.', 'The Disc Method', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid generated when the region under $y=x^2$ on $[0,2]$ is revolved about the $x$-axis.', '["$\\dfrac{32\\pi}{5}$", "$\\dfrac{16\\pi}{5}$", "$\\dfrac{32\\pi}{3}$", "$8\\pi$"]'::jsonb, 0, 'By the disc method, $V=\pi\int_0^2 (x^2)^2\,dx = \pi\int_0^2 x^4\,dx = \pi\left[\frac{x^5}{5}\right]_0^2 = \frac{32\pi}{5}$.', 'The Disc Method', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The region bounded by $y=x$, the $x$-axis, and $x=3$ is revolved about the $x$-axis. Find the volume of the resulting solid (a cone).', '["$9\\pi$", "$3\\pi$", "$27\\pi$", "$6\\pi$"]'::jsonb, 0, 'By the disc method, $V=\pi\int_0^3 x^2\,dx = \pi\left[\frac{x^3}{3}\right]_0^3 = 9\pi$.', 'The Disc Method', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The region bounded by $y=x^2$ and $y=4$ (for $x \geq 0$) is revolved about the $y$-axis. Using the shell method, which integral gives its volume?', '["$2\\pi\\displaystyle\\int_0^2 x(4-x^2)\\,dx$", "$2\\pi\\displaystyle\\int_0^4 x^2\\,dx$", "$\\pi\\displaystyle\\int_0^2 (4-x^2)^2\\,dx$", "$2\\pi\\displaystyle\\int_0^2 x(x^2-4)\\,dx$"]'::jsonb, 0, 'For a shell at position $x$ (from $x=0$ to $x=2$, where the curves meet), the shell has radius $x$, height $4-x^2$ (top minus the parabola), and thickness $dx$, giving $V=2\pi\int_0^2 x(4-x^2)\,dx$.', 'The Shell Method', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate the volume from the previous shell-method setup: $2\pi\displaystyle\int_0^2 x(4-x^2)\,dx$.', '["$8\\pi$", "$16\\pi$", "$4\\pi$", "$32\\pi$"]'::jsonb, 0, '$\int_0^2 (4x-x^3)\,dx = \left[2x^2-\frac{x^4}{4}\right]_0^2 = 8-4=4$. Multiplying by $2\pi$ gives $8\pi$.', 'The Shell Method', false, '', 0),
  ('mth-103-calculus', 'MTH 103: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the curve $y=\dfrac{2}{3}x^{3/2}$ from $x=0$ to $x=3$.', '["$\\dfrac{14}{3}$", "$\\dfrac{14}{9}$", "$2\\sqrt{3}$", "$\\dfrac{28}{3}$"]'::jsonb, 0, 'Since $y''=\sqrt{x}$, the arc length is $L=\int_0^3\sqrt{1+x}\,dx = \left[\frac23(1+x)^{3/2}\right]_0^3 = \frac23(8-1) = \frac{14}{3}$.', 'Lengths of Curves', false, '', 0);
